#!/usr/bin/env bash
# Check the carried compiler's source package without compiling a Wasm module.
set -euo pipefail
root=$(cd "$(dirname "$0")/.." && pwd)
. "$root/checks/env.sh"
t=$(mktemp -d)
trap 'rm -rf "$t"' EXIT
export LW_SELF_COMPILE_CACHE="$t/cache"
. "$root/checks/self-compile-module.sh"
sc_setup
# Only the packaged sources and pinned IR are available: root/src must not
# mask a missing dependency. Restore the snapshot generated by sc_setup.
if ! LW_RT_SNAPSHOT="$t/rt-snapshot.edn" "$LG" -source-paths "$lib" \
  -e "(require 'lwx.driver) (assert (resolve 'lwx.driver/compile-text))" > "$t/load.log" 2>&1; then
  cat "$t/load.log"
  exit 1
fi
echo "PASS self-host source dependencies: renamed driver loads from packaged sources"
